def attacher(code, scenes):
    """Donne à chaque scène sa phrase d'événement (champ evt) ; chaque scène doit en avoir une, une seule."""
    table = EVT[code]
    utilises = set()
    for s in scenes:
        t = s["titre"]["fr"]
        cles = [k for k in table if t.startswith(k)]
        assert len(cles) == 1, (code, t, cles)
        utilises.add(cles[0])
        s["evt"] = {"fr": table[cles[0]][0], "en": table[cles[0]][1]}
    assert utilises == set(table), (code, set(table) - utilises)
